export type TaxFormStatus = 'draft' | 'generated' | 'sent' | 'corrected' | 'voided'

export type TinType = 'ssn' | 'ein' | 'itin' | 'vat' | 'abn' | 'other'

export type LegalEntityType = 'individual' | 'sole_prop' | 'llc' | 's_corp' | 'c_corp' | 'partnership' | 'other'

